import java.util.List;

public class BoundedTypeDemo {
    // Bounded Generic Class: T must be a subclass of Number
    static class Stats<T extends Number> {
        private final List<T> numbers;

        public Stats(List<T> numbers) {
            this.numbers = numbers;
        }

        public double average() {
            if (numbers == null || numbers.isEmpty()) return 0.0;
            double sum = 0.0;
            for (T n : numbers) {
                // Directly invoke Number's doubleValue() without casting!
                sum += n.doubleValue();
            }
            return sum / numbers.size();
        }
    }

    public static void main(String[] args) {
        Stats<Integer> intStats = new Stats<>(List.of(10, 20, 30, 40));
        System.out.printf("Integer average: %.2f%n", intStats.average());

        Stats<Double> dblStats = new Stats<>(List.of(1.5, 2.5, 3.5));
        System.out.printf("Double average:  %.2f%n", dblStats.average());

        // Stats<String> bad = new Stats<>(List.of("a", "b")); // COMPILE ERROR!
    }
}
// Expected Output:
// Integer average: 25.00
// Double average:  2.50

