import java.util.List;

public class ComparableSearcher {
    // T is bounded by Comparable<T>, ensuring compareTo is available
    public static <T extends Comparable<T>> T findMinimum(List<T> list) {
        if (list == null || list.isEmpty()) return null;
        T min = list.get(0);
        for (int i = 1; i < list.size(); i++) {
            T current = list.get(i);
            if (current.compareTo(min) < 0) {
                min = current;
            }
        }
        return min;
    }

    public static void main(String[] args) {
        List<String> names = List.of("Zack", "Bob", "Charlie");
        System.out.println("Lexicographical min: " + findMinimum(names)); // Bob

        List<Integer> scores = List.of(95, 42, 88, 12);
        System.out.println("Numeric min:         " + findMinimum(scores)); // 12
    }
}

