practiceProblems.solutionCode:
public class NumberRange<T extends Number & Comparable<T>> {
    private final T min;
    private final T max;

    public NumberRange(T min, T max) {
        this.min = min;
        this.max = max;
    }

    public boolean contains(T value) {
        if (value == null) return false;
        return value.compareTo(min) >= 0 && value.compareTo(max) <= 0;
    }

    public static void main(String[] args) {
        NumberRange<Integer> range = new NumberRange<>(10, 50);
        System.out.println(range.contains(25));
        System.out.println(range.contains(5));
        System.out.println(range.contains(50));
    }
}

