import java.util.List;

public class SquareSumCalculator {
    public static <T extends Number> double sumOfSquares(List<T> numbers) {
        if (numbers == null) return 0.0;
        double sum = 0.0;
        for (T num : numbers) {
            if (num != null) {
                double val = num.doubleValue();
                sum += val * val;
            }
        }
        return sum;
    }

    public static void main(String[] args) {
        System.out.println(sumOfSquares(List.of(1, 2, 3)));
        System.out.println(sumOfSquares(List.of(2.0, 3.0, 4.0)));
    }
}

