practiceProblems.solutionCode:
public class GenericBinarySearch {
    public static <T extends Comparable<T>> int binarySearch(T[] array, T key) {
        if (array == null || key == null) return -1;
        int low = 0;
        int high = array.length - 1;

        while (low <= high) {
            int mid = (low + high) >>> 1;
            int cmp = array[mid].compareTo(key);
            if (cmp < 0) {
                low = mid + 1;
            } else if (cmp > 0) {
                high = mid - 1;
            } else {
                return mid;
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        Integer[] nums = {10, 20, 30, 40, 50};
        System.out.println(binarySearch(nums, 30));
        System.out.println(binarySearch(nums, 25));
    }
}

