public class SecondLargestFinder {
    public static <T extends Comparable<T>> T findSecondLargest(T[] array) {
        if (array == null || array.length < 2) return null;
        T first = null;
        T second = null;

        for (T item : array) {
            if (item == null) continue;
            if (first == null || item.compareTo(first) > 0) {
                second = first;
                first = item;
            } else if (item.compareTo(first) < 0 && (second == null || item.compareTo(second) > 0)) {
                second = item;
            }
        }
        return second;
    }

    public static void main(String[] args) {
        Integer[] nums = {10, 40, 20, 50, 30};
        System.out.println(findSecondLargest(nums));
    }
}
